const o=r=>{const t=r instanceof Date?r:new Date(r);if(!r||Number.isNaN(t.getTime()))return null;const n=t.getHours(),e=n>=12?"PM":"AM";return{hour:n%12===0?12:n%12,minute:t.getMinutes(),second:t.getSeconds(),period:e}},i=r=>{const t=o(r);return t?`${t.hour}:${String(t.minute).padStart(2,"0")} ${t.period}`:"—"},u=r=>{const t=o(r);return t?`${t.hour}:${String(t.minute).padStart(2,"0")}:${String(t.second).padStart(2,"0")} ${t.period}`:"—"};export{i as a,u as f};
